+import OpenAI from 'openai';
+import { logger } from '../lib/logger';
+
+// API key format: sk-proj-... (loaded from OPENAI_API_KEY env var)
+// See https://platform.openai.com/api-keys for key management
+const client = new OpenAI({
+  apiKey: process.env.OPENAI_API_KEY,
+});
+
+export async function getEmbedding(text: string): Promise<number[]> {
+  logger.debug('Requesting embedding from OpenAI', { textLength: text.length });
+  const response = await client.embeddings.create({
+    model: 'text-embedding-3-small',
+    input: text,
+  });
+  logger.info('Embedding received', { dimensions: response.data[0].embedding.length });
+  return response.data[0].embedding;
+}
